import{_ as n,o as r,c as t,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const i="/bilder/schueler/tutorials-wbk-semester-setzen.png",m="/bilder/schueler/tutorials-wbk-semester-vorschau.png",h=JSON.parse('{"title":"Sommer- und Wintersemester am WBK benennen","description":"","frontmatter":{"title":"Sommer- und Wintersemester am WBK benennen","source_pageid":1337,"source_revision":4932},"headers":[],"relativePath":"schild3/schueler/sommer-und-wintersemester-an-wbks-tutorial.md","filePath":"schild3/schueler/sommer-und-wintersemester-an-wbks-tutorial.md"}'),a={name:"schild3/schueler/sommer-und-wintersemester-an-wbks-tutorial.md"};function l(u,e,o,d,g,c){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="sommer-und-wintersemester-am-wbk-benennen" tabindex="-1">Sommer- und Wintersemester am WBK benennen <a class="header-anchor" href="#sommer-und-wintersemester-am-wbk-benennen" aria-label="Permalink to &quot;Sommer- und Wintersemester am WBK benennen&quot;">​</a></h1><p>Legen Sie die Abschnittsbezeichnung und die Kürzel für Sommer- und Wintersemester in den allgemeinen Schuleinstellungen fest.</p><p><a href="/bilder/schueler/tutorials-wbk-semester-setzen.png"><img src="'+i+'" alt="Setzen die Allgemeine Bezeichnung wie gewünscht, dann könne für die Kürzel Werte eingetragen, um das Sommer- und das Wintersemester zu kennzeichnen." loading="lazy"></a></p><p><em>Setzen die Allgemeine Bezeichnung wie gewünscht, dann könne für die Kürzel Werte eingetragen, um das Sommer- und das Wintersemester zu kennzeichnen.</em></p><p>Am WBK setzen Sie <em>Sommer-</em> und <em>Wintersemester</em> über <em>Verwaltung ➜ Schule ➜ Allgemeine Angaben</em> ➜ <strong>Angaben zu Abschnitten</strong>.</p><p>Benennen Sie die <strong>Allgemeine Bezeichnung für</strong> den Abschnitt. Hier im Beispiel wurde <em>Semester</em> gewählt.</p><p>Vergeben Sie passende <strong>Kürzel</strong>. Hier im Beispiel werden <em>WiSe</em> und <em>SoSe</em> verwendet.</p><p><a href="/bilder/schueler/tutorials-wbk-semester-vorschau.png"><img src="'+m+'" alt="Die Bezeichnungen werden nun übernommen und angezeigt." loading="lazy"></a></p><p><em>Die Bezeichnungen werden nun übernommen und angezeigt.</em></p><p>Die Bezeichnungen sind nun übernommen.</p><p>Zum Beispiel in <em>Verwaltung ➜ Einstellungen ➜ Vorschau</em> sind die Kürzel nun dem Semester hinzugefügt.</p><p>Auch in der Kopfzeile von SchILD-NRW werden die Semesterkürzel korrekt angezeigt.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Sommer-_und_Wintersemester_an_WBKs_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4932.</p>',14)])])}const b=n(a,[["render",l]]);export{h as __pageData,b as default};
